 if(source==='wipo-patentscope')return {source,mode:'interactive-reference',url:'https://patentscope.wipo.int/search/en/search.jsf',searchFor:query,retrieved:false,authority:'official-wipo-search',access:'Free website search; a free WIPO account adds saved searches and larger exports.',automaticPolling:false,reason:'No general free automation API has been established for this connector.',coverage:'PCT publications and participating national and regional collections. Coverage differs by office and field.',docs:'https://www.wipo.int/en/web/patentscope/faqs_patentscope'};
